"""Builds claims.json for the Retell account-phase lane (run with python3 -I)."""
import json
D='data/account-phase/retell/'
SDK=D+'sdk/npm-retell-sdk/x/package/src/resources/'
DATE='2026-10-20'
C=[]
def add(area,claim,grade,evidence):
    C.append({'id':'RAP-%02d'%(len(C)+1),'area':area,'claim':claim,'grade':grade,'evidence':evidence,'date':DATE})

# ---- access and surface
add('access','Our API key (name vp-teardown) is accepted as a Bearer token on https://api.retellai.com; GET /get-api-key-info returns our org name and key name. A sweep of all 38 documented GET operations (invalid probe ids where an id is needed) returned 200, 400 (missing required query) or 404 for 36, and 401 "Unauthorized: Invalid JWT" for 2 (get-contact-import, plus upload-contact-import-file on POST). Those two CSV-import routes are in the public OpenAPI and the SDKs but cannot be called with an API key.','observed',[D+'api-reads/get-api-key-info.json',D+'auth-sweep/summary.tsv',D+'api-writes/upload-contact-import-file.json'])
add('access','create-contact-import is reachable with the API key (a bogus upload_id gets a 400 schema error: upload ids match ^upload_[a-f0-9]+$), but a valid upload_id can only be minted by upload-contact-import-file, which needs a dashboard JWT. So bulk contact import with column mapping and default_country is dashboard-only in practice; the API path for loading leads is create-contact one at a time or batch-call tasks.','observed',[D+'api-writes/create-contact-import-bogus.json',D+'api-writes/upload-contact-import-file.json'])
add('access','The published SDKs expose exactly the public OpenAPI: parsing src/resources of retell-sdk 6.2.8 (npm) gives 109 method+path operations, identical to the 109 in the OpenAPI (revision 2026-10-19-becf7f8, byte-identical to the copy fetched in the public phase). No hidden routes, unlike Vapi\'s web SDK. The PyPI wheel retell-sdk 6.2.8 mirrors the same resources.','observed',[D+'derived/sdk-vs-openapi.json',D+'openapi/openapi.yaml','research/2026-10-20/account-phase/retell/manifest.csv'])
add('access','Rate limits are enforced per org and route group and are machine-readable: response headers show ratelimit-policy 100;w=10 on get/create/update/delete routes and 30;w=10 on list routes (RFC RateLimit-* headers plus X-RateLimit-Limiter on 429). This matches the docs table. Call creation is 1000/10 s with a 60 4xx/min cap, playground completions 8/2 s.','observed',[D+'api-reads/list-agents.headers.txt',D+'api-reads/get-concurrency.headers.txt','https://docs.retellai.com/get-started/sdk'])
add('access','Concurrency for our trial org: base 20, purchasable up to 180 more, burst enabled up to 60, reserved_inbound_concurrency exists as a field. Burst is on by default; the public rate card charges +USD 0.10/min for the whole call when burst is used.','observed',[D+'api-reads/get-concurrency.json',SDK+'concurrency.ts','https://docs.retellai.com/deploy/concurrency'])
add('access','There is no billing, balance, usage, spend-cap, member, workspace or analytics-aggregation operation among the 109 API operations. Credits, invoices, budget, team roles and dashboards are reachable only through a dashboard login.','observed',[D+'derived/endpoint-matrix.csv',D+'openapi/openapi.yaml'])
add('access','The Python and TypeScript SDK packages, the MCP server and the OpenAPI are all generated by Stainless from one backend spec (CHANGELOG: "sync OpenAPI from retell-backend"). The MCP server exposes two tools, search_docs and execute (TypeScript run against the SDK in a sandbox), not one tool per endpoint.','observed',[D+'sdk/npm-retell-sdk/x/package/CHANGELOG.md',D+'sdk/npm-mcp-server/x/package/src/instructions.ts'])
add('velocity','The retell-sdk changelog shows API-surface changes on 2026-10-08, 10-09, 10-13, 10-15 and 10-17 (6.2.4 to 6.2.8): SMS sender/destination options, is_transfer_agent, model_ultrafast, removal of the deprecated language "multi" scalar, removal of gpt-4.1-nano and claude-4.5-sonnet, a 409 on live takeover during PCI sessions. The spec changes about every two to three days.','observed',[D+'sdk/npm-retell-sdk/x/package/CHANGELOG.md'])
add('access','The live validator still lists "multi" among accepted language values even though the 6.2.8 changelog says the scalar was removed from the SDK types: the server is ahead of or behind the spec by at least one release.','observed',[D+'api-writes/val-lang-te.json',D+'sdk/npm-retell-sdk/x/package/CHANGELOG.md'])
add('access','Errors come in two shapes: JSON-schema failures are {"error_message":"request/body/<path> must ..."} (400) and business-rule failures are {"status":"error","message":"..."} (400/404/422). An unknown request field is silently ignored (a create-agent with "foo_unknown_field" returned 201). A nonexistent voice_id returns a bare 404 "Not Found" with no hint it was the voice.','observed',[D+'api-writes/val-unknown-field.json',D+'api-writes/val-voice-fake.json',D+'api-writes/val-pii-aadhaar.json'])

# ---- data model
add('data-model','Object graph, from the SDK types and live reads: agent (voice) or chat-agent points at one response engine: retell-llm (llm_id+version), conversation-flow (id+version) or a custom-LLM WebSocket. Agents and engines are versioned together (agent v0/v1 with llm v0/v1). Phone numbers hold weighted inbound/outbound/SMS agent lists. Calls, chats, contacts (CRM), batch calls, knowledge bases, apps (integration connections), MCP servers, test-case definitions/batches/runs, assets and export requests hang off the org. Workspaces and members are not in the API.','observed',[D+'api-writes/create-agent.json',D+'api-writes/create-agent-version.json',D+'derived/endpoint-matrix.csv'])
add('versioning','Version model: publish-agent-version freezes a version in place; PATCH /update-agent on a published version returns 422 "Cannot update published agent other than version title". create-agent-version(base_version) returns a new draft (is_published false, base_version recorded) and the response engine is cloned with it (agent v1 pointed at llm v1; get-retell-llm then returned version 1). PATCH ?version=1 edits the draft. Edit-in-place never publishes, unlike Vapi.','observed',[D+'api-writes/update-agent-after-publish.json',D+'api-writes/create-agent-version.json',D+'api-reads/list-agent-versions-synthetic-2.json',D+'api-reads/get-retell-llm-synth-after.json'])
add('data-model','Agents carry environment tags (the dashboard-seeded default agent had tags prod and staging); calls record agent_tag frozen at creation; create-phone-call can target override_agent_id plus override_agent_version (number, tag, latest or latest_published).','observed',[D+'api-reads/list-agents.json',SDK+'call.ts'])
add('data-model','Conversation flows (stateful graph builder) have 15 node types: conversation, subagent, end, function, code, transfer_call, press_digit, branch, sms, extract_dynamic_variables, agent_swap, mcp, component (reusable subflow), bridge_transfer, cancel_transfer. A created flow echoes back server defaults (skippable false, kb_config top_k 3 / filter_score 0.6). Edges carry prompt or equation transition conditions; global nodes have a condition, cool_down and go_back_conditions; nodes take finetune conversation and transition examples.','observed',[D+'api-writes/create-conversation-flow.json',D+'derived/sdk-flow-nodes-props.txt',SDK+'conversation-flow.ts'])
add('data-model','Per-node overrides exist on conversation and subagent nodes: stt_mode, custom_stt_config, boosted_keywords, voice_speed, responsiveness, interruption_sensitivity, reminder_trigger_ms/max_count, allow_dtmf_interruption, model_choice (cascading with high_priority/ultrafast, or s2s), knowledge_base_ids/kb_config, and skippable (skip the node when its questions are already answered in the conversation or saved contact memory).','observed',[D+'derived/sdk-flow-nodes-props.txt'])
add('data-model','Twelve tool types for the LLM engine: end_call, transfer_call (cold, warm, agentic warm; predefined or inferred destination), agent_swap (mid-call hand-off to another agent with keep_current_voice/language and its own webhook and post-call-analysis settings), press_digit, send_sms, custom (HTTP: url, method, headers, query_params, timeout_ms, max_retry, args_at_root, response_variables, speak_during/after_execution), code (JavaScript), extract_dynamic_variable, bridge_transfer, cancel_transfer, mcp (mcp_id, input_schema), integration_app (app_id, provider, templated tool). The server fills speak_after_execution true on tools.','observed',[D+'api-writes/create-retell-llm.json',SDK+'llm.ts'])
add('data-model','Agents can run integration tools before and after a call: pre_session_tools run as a dependency graph before the first message (about one minute budget, outputs injected as dynamic variables) and post_session_tools run after post-call analysis (five-minute budget), each gateable by a condition.','observed',[D+'derived/sdk-AgentResponse-props.txt'])

# ---- config knobs
add('config','Agent-level voice and turn-taking knobs (server accepted all in one create): voice_id, voice_model, voice_speed [0.5,2], voice_temperature [0,2], volume [0,2], enable_dynamic_voice_speed, enable_backchannel + backchannel_frequency [0,1] + backchannel_words, responsiveness [0,1], interruption_sensitivity [0,1], enable_dynamic_responsiveness, reminder_trigger_ms/reminder_max_count, begin_message_delay_ms [0,5000], end_call_after_silence_ms (min 10 s), max_call_duration_ms (1 min to 2 h, enforced: 10 ms was rejected), ring_duration_ms [5 s, 300 s], ambient_sound (6 presets) + volume, denoising_mode (3) + denoising_enhancement_level, stt_mode fast/accurate/custom, allow_user_dtmf + user_dtmf_options, fallback_voice_ids (cross-provider TTS failover), enable_expressive_mode + expressive_emotion_tags + expressive_mode_prompt.','observed',[D+'api-writes/create-agent.json',D+'api-writes/val-maxdur.json',D+'derived/sdk-AgentResponse-props.txt'])
add('config','Agent Handbook is a set of fixed prompt presets exposed as booleans in handbook_config: ai_disclosure, default_personality, conversational_personality, natural_filler_words, high_empathy, echo_verification, nato_phonetic_alphabet, speech_normalization, scope_boundaries, smart_matching. The docs say presets are fixed text and add token cost to every turn (ai_disclosure about 30 tokens, speech_normalization about 910).','observed',[D+'api-writes/create-agent.json','https://docs.retellai.com/build/agent-handbook'])
add('safety','A bare API create (only response_engine and voice_id) stores no handbook_config at all: no ai_disclosure key, no timezone, language en-US, pii_config categories empty, data_storage_setting everything. The dashboard-seeded default agent in the same org has handbook_config {ai_disclosure:true, default_personality:true}, interruption_sensitivity 0.9 and voicemail action hangup. The docs say new agents get AI Disclosure When Asked on by default; that holds for dashboard-created agents, and the key is absent for API-created ones. Inference: an API-built agent runs without the preset unless the caller sets it. Not tested on a live call.','observed',[D+'api-reads/get-agent-minimal-created.json',D+'api-reads/get-agent-default.json','https://docs.retellai.com/build/agent-handbook'])
add('config','Guardrails: guardrail_config has input_topics (only platform_integrity_jailbreaking) and output_topics (harassment, self_harm, sexual_exploitation, violence, defense_and_national_security, illicit_and_harmful_activity, gambling, regulated_professional_advice, child_safety_and_exploitation). There is no topic for misleading promotion, consent, or regulated financial advice by category beyond regulated_professional_advice, and nothing India-specific.','observed',[D+'api-writes/create-agent.json',D+'derived/sdk-AgentResponse-props.txt'])
add('config','Post-call analysis: fixed output (call_successful, call_summary, in_voicemail, user_sentiment) plus custom fields typed string, enum, boolean, number (and more) each with optional conditional_prompt, produced by a separately selectable post_call_analysis_model (default gpt-5.6-terra). rerun-call-analysis and backfill-contact-analysis-data endpoints exist. Custom fields are echoed per agent version in list-agent-versions.','observed',[D+'api-writes/create-agent.json',D+'api-reads/list-agent-versions-synthetic.json',D+'derived/sdk-call-subobjects.txt'])
add('config','Data handling knobs per agent: data_storage_setting (everything, everything_except_pii, basic_attributes_only), data_storage_retention_days (1 to 730), opt_in_signed_url with 24 h default expiry, pii_config with 14 categories and mode post_call only. The categories are person_name, address, email, phone_number, ssn, passport, driver_license, credit_card, bank_account, password, pin, medical_id, date_of_birth, customer_account_number; "aadhaar" was rejected with a 400. No India ID types (Aadhaar, PAN) and no real-time redaction.','observed',[D+'api-writes/val-pii-aadhaar.json',D+'api-writes/create-agent.json'])
add('config','Voicemail and IVR options: voicemail_option.action is one of prompt (LLM speaks), static_text, hangup, bridge_transfer, with an optional detection_prompt; ivr_option supports only hangup, with optional detection_prompt; call_screening_option holds agent_identity and call_purpose strings. Detection windows are the first three minutes per the SDK text. enable_dnc_detection is a boolean; the confirmation script is fixed.','observed',[D+'derived/sdk-AgentResponse-props.txt',D+'api-writes/create-agent.json'])
add('config','Custom STT: stt_mode custom takes custom_stt_config {provider: azure|deepgram|soniox|assemblyai|muse, endpointing_ms}. boosted_keywords bias recognition and accept {{dynamic_variable}} templates. pronunciation_dictionary entries accept alphabets ipa, cmu, pinyin or jyutping only; no Devanagari or Indic-script alphabet.','observed',[D+'derived/sdk-AgentResponse-props.txt'])
add('config','Language is an agent-level locale or array of locales (["hi-IN","en-IN"] accepted and echoed). The live validator lists 63 locales; India: en-IN, hi-IN, kn-IN, mr-IN, ta-IN, ur-IN. te-IN (Telugu) is rejected with a 400 that lists the allowed values. There is no Bengali, Gujarati, Malayalam, Punjabi or Odia, and no per-turn language-ID setting.','observed',[D+'api-writes/val-lang-te.json',D+'api-writes/create-agent.json'])
add('config','Brains: the Retell LLM engine accepts 32 cascading models (OpenAI gpt-4.1 through gpt-6.1-sol, Anthropic claude-4.5-haiku through claude-5.5-opus, Google gemini-3.0-flash through gemini-4-argon) and 6 speech-to-speech models (gpt-realtime family); s2s_model and model are mutually exclusive. Priority tiers: model_high_priority and model_ultrafast (ultrafast only on gpt-6.1-sol). No open-weight or Indian-lab model is listed.','observed',[D+'derived/sdk-LlmResponse-props.txt',SDK+'llm.ts'])
add('config','Voice-model validation is provider-specific: voice_model eleven_v3 on an Inworld voice returned 400 "Selected voice model eleven_v3 is not supported for this voice provider". The voice_model enum has 20 values across ElevenLabs (flash v2/v2.5, multilingual v2, v3, v3 conversational, v4, v4 turbo), Cartesia (sonic-3 to 3.6), OpenAI (tts-1, gpt-4o-mini-tts), MiniMax (speech-02-turbo, 2.8-turbo), Fish (s1, s2-pro, s2.1-pro) and Inworld (tts-2, tts-2-flash).','observed',[D+'api-writes/val-voice-model-mismatch.json',SDK+'agent.ts'])

# ---- voices
add('voices','GET /list-voices returns 300 standard voices from 7 providers: cartesia 88, elevenlabs 64, minimax 39, openai 34, inworld 29, fish_audio 25, platform 21. The voice object has no language field. Only 6 voices have accent "Indian" (elevenlabs Samad, Monika, Amritanshu labelled en-IN; inworld Saanvi and Nikhil; openai Monika), 2 percent of the catalogue; 42 are flagged recommended.','observed',[D+'api-reads/list-voices.json'])
add('voices','Hindi voices exist only through the community library search: POST /search-community-voice with query "hindi" returned up to 100 ElevenLabs results, 99 Cartesia, 20 Fish, 6 Inworld and 3 MiniMax (counts are what was returned, which may be capped). Adding one to the account is a separate add-community-voice call (not executed).','observed',[D+'api-reads/voice-search-hindi-elevenlabs.json',D+'api-reads/voice-search-hindi-cartesia.json',D+'api-reads/voice-search-hindi-inworld.json',D+'api-reads/voice-search-hindi-minimax.json',D+'api-reads/voice-search-hindi-fish_audio.json'])
add('architecture','The 21 "platform" (retell-*) voices are not distinguishable from third-party voices by their preview assets: 15 preview files are named minimax-*/minimax_*, 2 fish_audio-*, 1 cartesia-*, and only 3 (retell-Lily, retell-Ashley, rita) carry no provider tag. Cartesia voice previews sit in a folder named cartesia-sonic-3.6-2026-09-08. Inference: Retell "Platform Voices" are mostly re-listed MiniMax/Fish/Cartesia voices at the USD 0.015 TTS rate, not an in-house TTS. This is inferred from file names, not from audio or traffic.','inferred',[D+'api-reads/list-voices.json','https://www.retellai.com/pricing'])

# ---- memory / CRM
add('memory','Contact memory: agents have contact_memory_config {enable_read, enable_update}; an API-created agent defaults to read on, update off (a dashboard-created default showed the same). The org CRM config exposes the default memory-update prompt (observed text): rewrite one running brief of the contact, keep only what would change what an agent says or does, drop resolved items, no sentiment or personality guess, plain prose, under 2000 characters, treat transcript as data. The prompt can be overridden org-wide via contact_memory_update_prompt (null here).','observed',[D+'api-reads/get-crm-config.json',D+'api-reads/get-agent-default.json',D+'api-writes/create-agent.json'])
add('memory','Memory is a per-contact text field plus conversation list, not retrieval: contact has contact_memory (string), custom_fields, contact_tags, do_not_call, conversation_count, last_conversation_timestamp; list-contact-conversations returns calls and chats with direction, disconnection_reason, duration, sentiment. Conversation-flow nodes can set skippable to skip questions already answered in memory.','observed',[D+'derived/sdk-flow-nodes-props.txt',SDK+'contact.ts','https://docs.retellai.com/features/contact-memory'])
add('india','CRM contact create does no Indian-number handling: a 10-digit Indian mobile "9000000001" was stored as "+19000000001" (US country code added, no warning), "09000000003" was stored verbatim, "12345" was accepted, and "+919000000002" was stored as given. Uniqueness is on the exact string: a second "+919000000002" returned 400 "already exists", but "+919000000003" and "09000000003" coexisted, so the same subscriber can be two contacts. do_not_call can be set on create. All six probe contacts were deleted.','observed',[D+'api-writes/create-contact-plain10.json',D+'api-writes/create-contact-zero.json',D+'api-writes/create-contact-short.json',D+'api-writes/create-contact-dupe.json',D+'api-writes/create-contact-e164-twin.json',D+'api-writes/create-contact-dnc.json'])

# ---- calls / lifecycle / webhooks
add('lifecycle','Call state: call_status is registered, not_connected, ongoing, ended or error. disconnection_reason has 39 values that double as the failure taxonomy: not_connected = dial_busy, dial_failed, dial_no_answer, invalid_destination, telephony_provider_*, sip_routing_error, marked_as_spam, network_blocked, user_declined; error = concurrency_limit_reached, no_valid_payment, credit_exhausted, budget_reached, scam_detected, error_llm_websocket_*, error_no_audio_received, error_asr, error_retell, error_user_not_joined, registered_call_timeout (phone call 5 minutes or more after registration); ended = user_hangup, agent_hangup, user_requested_dnc, user_requested_callback, call_transfer, transfer_bridged/cancelled, voicemail_reached, ivr_reached, inactivity, max_duration_reached, no_concurrency_fallback, manual_stopped, call_take_over. Reasons are engineering codes; the business outcome lives in call_analysis (custom fields).','observed',[D+'derived/sdk-call-subobjects.txt','https://docs.retellai.com/reliability/debug-call-disconnect'])
add('lifecycle','Call object: agent_id/agent_version/agent_tag, direction, from/to, timestamps, duration_ms, transcript (string, word-timestamped transcript_object, and transcript_with_tool_calls with scrubbed variants), recording_url and multichannel and scrubbed variants, public_log_url, call_analysis, call_cost {combined_cost, product_costs[], total_duration_seconds, total_duration_unit_price}, latency {asr, e2e, knowledge_base, llm, llm_websocket_network_rtt, s2s, tts}, llm_token_usage {average, num_requests, values[]}, collected_dynamic_variables, retell_llm_dynamic_variables, metadata (50 kB), telephony_identifier {twilio_call_sid}, transfer_destination. The only telephony identifier typed is a Twilio call sid.','observed',[D+'derived/sdk-PhoneCallResponse-props.txt',D+'derived/sdk-call-subobjects.txt'])
add('architecture','telephony_identifier is typed with only twilio_call_sid, number_provider is twilio or telnyx for purchased numbers, and phone_number_type is retell-twilio, retell-telnyx or custom. Inference: Retell-managed PSTN is carried by Twilio (default) or Telnyx, consistent with the Twilio-style per-call fields; no call was placed to confirm.','inferred',[D+'derived/sdk-PhoneCallResponse-props.txt',D+'derived/sdk-batch-phone.txt'])
add('lifecycle','Outbound calling API: create-phone-call takes from_number (owned or imported), to_number (Retell-purchased numbers: US destinations only per the SDK text), override_agent_id/version, agent_override (agent, retell_llm and conversation_flow subsets), retell_llm_dynamic_variables, metadata, custom_sip_headers, ignore_e164_validation (custom telephony only), idempotency_key (retry safe for one hour), and honor_internal_dnc which defaults to false. register-phone-call and a dial-to-SIP path exist for custom telephony. Not executed.','observed',[D+'derived/sdk-create-phone-call-params.txt',SDK+'call.ts'])
add('lifecycle','Batch calls (create-batch-call only; no list, get, cancel or status route in the 109 operations): inputs are from_number, tasks[] each with to_number plus optional per-task agent override, dynamic variables, metadata, SIP headers; call_time_window {windows[], day[], timezone default America/Los_Angeles; half-open minute intervals; no cross-midnight}; reserved_concurrency; trigger_timestamp. The response carries only batch_call_id, name, from_number, scheduled_timestamp, total_task_count and the window. No retry, attempt or pacing field exists. Not executed (billable +USD 0.005/dial).','observed',[D+'derived/sdk-batch-phone.txt','https://docs.retellai.com/deploy/make-batch-call'])
add('lifecycle','Live control while a call runs: update-live-call accepts call_control {additional_context (appended to the transcript with role "injected" and fed to the next response), trigger_response (interrupt and regenerate, or nudge)} and fields_to_override {metadata, override_dynamic_variables, data_storage_setting (cannot be loosened)}; listen-live-call returns a subscribe-only JWT, participant_id, room_name and ICE servers on a livekit or gateway transport; take-over-live-call upgrades the listener and permanently stops the agent (disconnection call_take_over; 409 while a PCI session is active); stop-call ends it.','observed',[SDK+'call.ts',D+'derived/sdk-call-subobjects.txt'])
add('webhooks','Webhook events per agent (webhook_events, default call_started, call_ended, call_analyzed): call_started, call_ended, call_analyzed, transcript_updated, transfer_started, transfer_bridged, transfer_cancelled, transfer_ended; chats get chat_started/ended/analyzed. Envelope {event, call:{...}} (transfer events add transfer_destination and transfer_option). x-retell-signature is "v=<ms>,d=<hex>" where d = HMAC-SHA256(rawBody + timestamp) keyed with the API key that carries the webhook badge, 5-minute tolerance. 10 s timeout, up to 3 retries, one published egress IP (100.20.5.228), private and metadata addresses blocked. agent webhook_url overrides the account-level URL and supports {{dynamic_variable}} templating. We registered an example.invalid URL only; no delivery was observed.','observed',[D+'sdk/npm-retell-sdk/x/package/src/lib/webhook_auth.ts',D+'api-writes/create-agent.json','https://docs.retellai.com/features/webhook-overview'])
add('webhooks','Inbound call and SMS webhook is configured per phone number (not per agent): Retell POSTs {event:"call_inbound", call_inbound:{call_id, agent_id, agent_version, from_number, to_number, custom_sip_headers}} before the call exists, and the customer\'s 2xx JSON reply under call_inbound can reject the call or override agent, dynamic variables and metadata. Up to 3 attempts at 10 s. This is a pre-answer decision hook.','observed',[D+'derived/sdk-batch-phone.txt','https://docs.retellai.com/features/inbound-call-webhook'])
add('lifecycle','Custom-LLM protocol (llm_websocket_url): Retell connects to the customer\'s WebSocket; events config, call_details, update_only, response_required, reminder_required, ping_pong; the server replies with response_type config/response/ping_pong. With auto_reconnect, 5 s without a ping_pong echo closes and reconnects; after 2 reconnects the call ends with error_llm_websocket_lost_connection. Retell keeps telephony, ASR, TTS and turn-taking; the buyer owns only the brain.','observed',[D+'derived/sdk-call-subobjects.txt','https://docs.retellai.com/integrate-llm/setup-websocket-server'])
add('architecture','Web client SDK retell-client-js-sdk 3.0.2 (REA javascript-application analysis, 336 graph nodes, 35 endpoint nodes): the new gateway transport signals to api.retellai.com/webrtc-proxy/<call_id>/v1/webrtc/sessions (POST offer SDP with identity "client", PATCH trickle ICE, DELETE to end), then sends media straight to the gateway address in the SDP answer; default ICE server is stun.l.google.com:19302; a "control" data channel is created but unused; LiveKit transport (wss://retell-ai-4ihahnq7.livekit.cloud) remains as legacy. This refines the public-phase finding with exact paths.','observed',[D+'sdk/npm-client-js/x/package/src/gateway-transport.ts',D+'rea/client-js-rea-summary.json',D+'rea/client-js-analyze.json.gz'])

# ---- analytics / testing
add('analytics','Analytics in the API are list-calls filters, not aggregates: POST /v3/list-calls takes filter_criteria with about 25 dimensions (agent, agent_tag, batch_call_id, call_status, call_successful, call_type, combined_cost, custom_analysis_data, custom_attributes, data_storage_setting, direction, disconnection_reason, duration_ms, dynamic_variables, e2e_latency_p50 per call, in_voicemail, metadata, timestamps, from/to number, tool_calls, user_sentiment), sort by start_timestamp, include_total optional (extra aggregation cost). There is no group-by, funnel, cohort or time-series endpoint. The dashboard charts and alerts (14 metrics per the public phase) are login-only.','observed',[SDK+'call.ts',D+'derived/endpoint-matrix.csv'])
add('testing','Simulation tests: a test-case definition is {name, type simulation, response_engine, user_prompt (the simulated caller), metrics[] (free-text criteria judged by an LLM), dynamic_variables, tool_mocks[] (any or partial_match on args), llm_model}; batch tests run many definitions against a pinned engine version; runs have status pending, in_progress, pass, fail, error with result_explanation. Listing needs type=retell-llm|conversation-flow plus llm_id or conversation_flow_id. We created and deleted one definition; no run was started because runs are billed.','observed',[D+'api-writes/create-test-case-definition.json',D+'api-reads/list-test-case-definitions-synth.json',SDK+'tests.ts'])
add('testing','Export is list-only in the API (list-export-requests returns channel, status created/processing/completed/error, timezone, url); creation of an export is a dashboard action. Call history export therefore cannot be scripted with an API key.','observed',[D+'api-reads/list-export-requests.json',D+'derived/endpoint-matrix.csv'])

# ---- phone numbers / india
add('telephony','Number purchase accepts country_code US or CA only (provider twilio or telnyx; area_code US only). import-phone-number takes phone_number, termination_uri and optional SIP trunk username/password, and defaults ignore_e164_validation to true. Per-number controls: weighted inbound_agents/outbound_agents (weights sum to 1), inbound/outbound SMS agents, inbound_webhook_url, fallback_number when concurrency is exhausted, allowed_inbound_country_list and allowed_outbound_country_list (ISO codes), transport TLS/TCP/UDP (default TCP). No number was bought, imported or listed (the account has none).','observed',[D+'derived/sdk-batch-phone.txt',D+'api-reads/list-phone-numbers.json'])
add('india','India plumbing absent from the typed API: no object or field in 109 operations or about 320 schemas for DLT/header registration, 140/160 series, NCPR/DND scrub, consent record, calling category or TRAI window. Calling windows are generic minute intervals per IANA timezone with US default. The only compliance primitives are do_not_call on a contact (honoured by create-phone-call only if honor_internal_dnc is true), enable_dnc_detection, allowed_outbound_country_list, guardrail topics and PII scrubbing.','observed',[D+'derived/endpoint-matrix.csv',D+'derived/sdk-batch-phone.txt',D+'openapi/openapi.yaml'])
add('india','India-specific product depth visible in the API is thin: 6 India locales out of 63, 6 of 300 voices flagged Indian accent and none labelled Hindi, pronunciation alphabets with no Indic script, PII categories with no Indian ID, a US default for timezone, window timezone and contact import, and a CRM that rewrites 10-digit Indian numbers to +1. Inference: India is served as an add-on locale of a US-first product.','inferred',[D+'api-writes/val-lang-te.json',D+'api-reads/list-voices.json',D+'api-writes/val-pii-aadhaar.json',D+'api-writes/create-contact-plain10.json'])

# ---- billing / metering
add('billing','Metering as exposed by the API: each call carries call_cost.product_costs[] with {product, unit_price (cents per second), cost (cents), is_transfer_leg_cost}, a total_duration_seconds and a combined_cost in cents; llm_token_usage gives the per-request token counts that the public docs use for the 4,000-token billed-duration scaling. The same structure exists for chats (chat_cost). Product names are strings (the spec example is "elevenlabs_tts"). Costs appear only after a call ends. We placed no call, so no real product list, per-second price or scaling was observed.','observed',[D+'derived/sdk-call-subobjects.txt',D+'openapi/openapi.yaml'])
add('billing','The resources we created and read (LLM, agents, versions, conversation flow, test definition, contacts, voice search, concurrency) are not metered line items in the published rate card; the public rate card bills calls, chats, KB beyond 10 free, numbers, concurrency, CPS and add-ons. We cannot read the credit balance with an API key, so unchanged balance is inferred from the rate card rather than observed.','inferred',[D+'api-reads/final-list-agents.json','https://www.retellai.com/pricing','https://docs.retellai.com/accounts/billing'])

